// What to do next. It returns the demand and where to read it, and NEVER the keys: they are in Register Free Key's output
// only (shown once). Copy api_key from there into a Taifoon Relayer API credential, then use template 10.
const r = $json || {};
const d = r.demand || {};
const id = d.id || null;
return [{ json: {
  demand: id, state: d.state || null, class: d.class || null,
  read: id ? `https://coord.taifoon.dev/v1/demands/${id}` : null,
  explorer: id ? `https://www.taifoon.io/scan/jobs/${id}` : null,
  error: id ? null : (r.error || r.message || 'the sample demand was not accepted'),
  next_steps: [
    'Open the Register Free Key node output and copy api_key (it is shown once and is not repeated here).',
    'In n8n: Credentials → New → Taifoon Relayer API → paste it as API Key → Save.',
    'Import 10-buy-through-taifoon.json, attach that credential to the two Demand nodes, press Execute.',
    'Delete this execution (or keep "save successful executions" off) so the keys do not stay in execution data.',
  ],
} }];
